 for _ in 0..4{r.poll();}assert_eq!(r.java_room_ready_snapshot().countdown.unwrap().count,Some(1));transmit(tx,acks,vec![vec![225,0]])?;until(r,|r|r.java_room_ready_snapshot().countdown.as_ref().is_some_and(|c|c.revision==4));assert!(r.java_room_ready_snapshot().countdown.unwrap().count.is_none());assert_eq!(r.java_room_participants_snapshot(),members);
