 transmit(tx,acks,vec![vec![254]])?;r.disconnect_source_connection_candidate(&epoch)?;until(r,|r|r.player_fixture_snapshot().workers_started==r.player_fixture_snapshot().workers_joined);assert_eq!(r.last_java_room_ready_checkpoint(),Some(archived));resume_setup(r)?;until(r,|r|r.java_character_snapshot().stage==lito_modern::modern_lito::native_city_runtime::java_character_flow::Stage::ChannelReceipts);enter_room(r,data,tx,acks,2)?;assert!(r.java_room_ready_snapshot().countdown.is_none());let before=r.presentation_key();assert!(r.handle_java_room_ready_control(&stale).is_err());assert!(r.consume_java_room_countdown_candidate(&old_tick).is_err());assert_eq!(r.presentation_key(),before);
 transmit(tx,acks,vec![vec![225,2]])?;until(r,|r|r.java_room_ready_snapshot().countdown.is_some());assert_eq!(r.java_room_ready_snapshot().countdown.unwrap().room_id,2);
 // Same-epoch packets carry no room/generation. We only label current receipt
