 Ok(vec![json!({"case":"ONE ownsynthetic normal-entry two sequential source/room epochs; trueC_D2 2/1/0 frame4 read and fullwrite only; D1 independent; E1 3/2/1,E100 clears countdown without clearingready;poll has noWORLDgrant","pass":true,"participant_requests":3,"D1_updates":4,"E1_receipts":6,"actual485Fbackend":false}),json!({"case":"revision/clone/pending/foreign/CF/source/room switch guards; owner opcode-only refused despiteCEownerdisplay; second room newE1 receipt is not freshness proof; firstunsupported genuine savedWORLD marker stops","pass":true,"first_unsupported":"28340200","reason":rejection.reason,"same_epoch_stale_detection_proved":false,"committed_leave":false})])
